"""cue -- conditional cue/response mark, DETECTOR ONLY.
"""
from __future__ import annotations

import numpy as np
import pandas as pd
from ..prf import domain_id, prf_unit
from ._stats import loo_residual


NAME = "cue"


def waveforms(key: bytes, lc: int, lr: int) -> tuple[np.ndarray, np.ndarray]:
    """Keyed band-limited noise (3-tap smoothing), zero-mean, unit RMS."""
    def wf(label, n):
        u = prf_unit(key, domain_id("cue:" + label), np.arange(n + 2))
        g = np.sqrt(-2 * np.log(np.clip(u, 1e-12, 1))) * np.cos(2 * np.pi * prf_unit(key, domain_id("cue2:" + label),
                                                                                       np.arange(n + 2)))
        w = np.convolve(g, np.ones(3) / 3, mode="valid")[:n]
        w = w - w.mean()
        return w / (np.sqrt(np.mean(w ** 2)) + 1e-12)
    return wf("cue", lc), wf("resp", lr)


def anchors(key: bytes, col: str, n: int, spacing: int, lc: int, lr: int) -> np.ndarray:
    m = n // spacing
    jit = prf_unit(key, domain_id("cueanchor:" + col), np.arange(m))
    p = (np.arange(m) * spacing + lc + (jit * max(spacing - lc - lr, 1)).astype(int))
    return p[(p - lc >= 0) & (p + lr <= n)]


def _copy_stat(df, key, params):
    lc, lr, sp = params["lc"], params["lr"], params["spacing"]
    cue, resp = waveforms(key, lc, lr)
    tpl = np.concatenate([cue, resp])
    tot = 0.0
    for c in params["columns"]:
        if c not in df.columns:
            continue
        x = df[c].to_numpy(np.float64)
        r = loo_residual(np.where(np.isfinite(x), x, np.nanmedian(x)))
        ps = anchors(key, c, len(x), sp, lc, lr)
        if ps.size:
            seg = np.stack([r[p - lc:p + lr] for p in ps])
            tot += float(np.sum(seg @ tpl) / (np.sqrt(np.sum(seg ** 2)) * np.sqrt(np.sum(tpl ** 2)) + 1e-12))
    return tot


def detect(df: pd.DataFrame, key: bytes, params: dict, n_decoys: int = 200, **_):
    """Copy detection by key exchangeability: matched-filter score at the owner's anchors vs. decoy keys
    (the anchors and waveforms are pure functions of the key, so the permutation p-value is exact)."""
    from ..decoys import decoy_keys
    s = _copy_stat(df, key, params)
    d = np.array([_copy_stat(df, k, params) for k in decoy_keys(n_decoys, 7)])
    p = float((1 + np.sum(d >= s)) / (1 + n_decoys))
    z = float((s - d.mean()) / (d.std() + 1e-12))
    return {"method": NAME, "z": z, "p": p, "p_floor": 1 / (1 + n_decoys), "stat": s}
